-- MySQL 8. Structure only; no invented leadership assignments.
CREATE TABLE IF NOT EXISTS organization_units(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,name VARCHAR(120) NOT NULL,parent_id BIGINT NULL,branch_id BIGINT NULL,active BIT NOT NULL DEFAULT b'1') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS job_titles(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,name VARCHAR(120) NOT NULL,active BIT NOT NULL DEFAULT b'1') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS organization_assignments(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,account_id BIGINT NOT NULL,unit_id BIGINT NOT NULL,title_id BIGINT NOT NULL,manager_account_id BIGINT NULL,active BIT NOT NULL DEFAULT b'1',UNIQUE KEY uk_org_assignment(account_id,unit_id,title_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS internal_support_tickets(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,owner_id BIGINT NOT NULL,branch_id BIGINT NULL,category VARCHAR(30) NOT NULL,title VARCHAR(120) NOT NULL,description VARCHAR(3000) NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,INDEX idx_internal_owner_branch(owner_id,branch_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS internal_support_replies(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,message VARCHAR(2000) NOT NULL,status_after VARCHAR(20) NOT NULL,created_at DATETIME(6) NOT NULL,INDEX idx_internal_replies(ticket_id,id)) ENGINE=InnoDB;
